import React, { useState } from 'react';
import type { Options, Value } from '@react-page/editor';
import Editor from '@react-page/editor';
import slate from '@react-page/plugins-slate';



import customContentPlugin from './customContentPlugin';

const cellPlugins = [slate(), customContentPlugin];

const LANGUAGES = [
  {
    lang: 'en',
    label: 'English',
  },
  {
    lang: 'de',
    label: 'Deutsch',
  },
];

// Custom bottom toolbar example with collapse/restore functionality.
const languageSwitchExample = () => {
  const [lang, setLang] = React.useState<string>('en');
  const [value, setValue] = useState<Value>();

  React.useEffect(()=>{if(__TEST__)(window as any).__RP={value,lang};return()=>{if(__TEST__)delete (window as any).__RP}},[value,lang]);
  return (
    <>
      <select value={lang} onChange={(v) => setLang(v.target.value)}>
        {LANGUAGES.map((l) => (
          <option key={l.lang} value={l.lang}>
            {l.label}
          </option>
        ))}
      </select>
      <Editor
        languages={LANGUAGES}
        cellPlugins={cellPlugins}
        value={value}
        onChange={setValue}
        lang={lang}
        onChangeLang={(l) => {
          setLang(l);
        }}
      />
    </>
  );
};

